    p_t1.paragraph_format.space_after = Pt(4)
    r_t1 = p_t1.add_run("ตารางที่ 2.1 ความหมายระดับความรุนแรง 5 ระดับที่นำมาใช้เป็นแนวคิดของโครงงาน")
    set_run_font(r_t1, size_pt=16, bold=True)
    
    t1 = doc.add_table(rows=6, cols=4)
    col_w1 = [Inches(0.6), Inches(0.9), Inches(2.2), Inches(2.3)]
    headers1 = ["ระดับ", "รหัสสี", "ความหมายโดยสรุปตามเกณฑ์ MOPH", "แนวทางการจัดการในโครงงาน"]
